import { Object3D, PlaneGeometry, Mesh } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // Load texture (atlas)
  const tex = ctx.textureLoader(config.assets.imageUrl);

  // Determine aspect ratio from atlas region (width / height)
  const srcRect = config.atlasRegion?.sourceRect ?? { width: 1, height: 1 };
  const aspect = srcRect.width / srcRect.height || 1;

  // Plane geometry sized to aspect ratio (height = 1 unit)
  const geometry = new PlaneGeometry(aspect, 1);
  // Node material with texture map
  const material = new MeshBasicNodeMaterial({ map: texture(tex) });

  const mesh = new Mesh(geometry, material);
  mesh.position.set(0, -0.3, 0);
  mesh.scale.set(1, 1, 1);
  mesh.rotation.set(0, 0, 0);

  // Billboard: always face camera
  mesh.onBeforeRender = (_, __, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  // No primitives to apply per spec
  // Store handlers placeholder
  mesh.userData.handlers = {};

  // Cleanup resources and any GSAP timelines
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    tex.dispose && tex.dispose();
    gsap.globalTimeline.clear();
  };

  return mesh;
}
